def backfill_phone_canon(apps, schema_editor):
    """tagada2: fill KhataParty.phone_canon for existing rows (save() keeps it
    in step from now on). Batched; unparseable numbers stay ''."""
    from core.phone import canonical_phone
    KhataParty = apps.get_model("core", "KhataParty")
    qs = KhataParty.objects.exclude(phone="").only("id", "phone")
    batch = []
    for p in qs.iterator(chunk_size=1000):
        c = canonical_phone(p.phone or "") or ""
        if c:
            p.phone_canon = c
            batch.append(p)
        if len(batch) >= 500:
            KhataParty.objects.bulk_update(batch, ["phone_canon"])
            batch = []
    if batch:
        KhataParty.objects.bulk_update(batch, ["phone_canon"])


